export function getMZMLAProfile(acNo: number): MLAProfile | undefined {
  return MZ_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getMZMLAsByParty(party: string): MLAProfile[] {
  return MZ_MLA_PROFILES.filter(p => p.party === party);
}

export function getMZFemaleMLAs(): MLAProfile[] {
  return MZ_MLA_PROFILES.filter(p => p.gender === 'F');
}
